const tpState={domain:'全部',mode:'全部',preview:'正常',tabs:{},provider:'veo',selected:[1,2,1],drafts:{},gates:{}};
const tpProjects={p5:{name:'品牌短片',domain:'VIDEO'},p6:{name:'长篇小说《潮汐之城》',domain:'NOVEL'},p7:{name:'市场活动筹备',domain:'TEAM_TASKS'}};
function tpEsc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function tpBtn(t,action,kind='',reason=''){return `<span class="stack" style="gap:4px;align-items:flex-start"><button class="btn ${kind}" onclick="${tpEsc(action)}" ${reason?'disabled':''}>${t}</button>${reason?`<span class="muted xs">${reason}</span>`:''}</span>`;}
function tpBadge(t,k='info'){return `<span class="badge b-${k}">${t}</span>`;}
function tpTable(h,rows){return `<div class="table-wrap"><table><thead><tr>${h.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function tpKV(rows){return `<dl class="kv">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;}
function tpSet(k,v){tpState[k]=v;route();}
function tpTabs(key,labels){const n=tpState.tabs[key]||0;return `<div class="tabs" role="tablist" aria-label="内容标签">${labels.map((t,i)=>`<button role="tab" aria-selected="${n===i}" class="${n===i?'on':''}" onclick="tpTab('${key}',${i})">${t}</button>`).join('')}</div>`;}
function tpTab(k,n){tpState.tabs[k]=n;route();}
function tpPreview(){return `<div class="row wrap"><span class="small muted">状态预览</span>${['正常','异常','空'].map(t=>`<button class="chip ${tpState.preview===t?'on':''}" onclick="tpSet('preview','${t}')">${t}</button>`).join('')}</div>`;}
function tpV(name,kind,applies,params,override=false,lim='只证明本检查范围'){return {name,kind,applies,params,override,lim};}
