function tpCases(k){const names={SOFTWARE:['棋盘网格行高不一致','冻结测试被修改','直接打开交付形态'],VIDEO:['中段黑场未拦截','字幕对齐偏差 280 ms','合规广播响度'],NOVEL:['角色时间线矛盾','跨章重复超过 2%','有意保留伏笔'],TEAM_TASKS:['过期交付链接','状态草稿与系统冲突','指定角色签收']};return Array.from({length:24},(_,i)=>({id:`${k}-评测-${i+1}`,title:names[k][i%3]+` · 场景 ${Math.floor(i/3)+1}`,source:i<18?'SEED':i<21?'ESCAPE':'MANUAL',input:`文件-${k}-${i+1}`,expected:i%3===2?'通过':'不通过',escape:i>=18&&i<21?`穿透-${k}-${i-17}`:'—'}));}
