function tpCreate(k){openModal(`<div class="stack" style="padding:24px"><h3>用${tpTemplates[k].name}模板新建项目</h3>${tpKV([['锁定版本','1.0.0'],['升级策略','锁定；不自动接受后续版本'],['初始阶段',tpTemplates[k].stages[0].split('|')[0]],['团队模式',tpTemplates[k].modes.join('、')]])}<div class="note info">此原型仅展示模板选择与绑定摘要，未接入新建项目提交。</div>${tpBtn('关闭','closeModal()','primary')}</div>`);}
